import { ProviderContext } from '@/context/StoreContext';
import {
  Box,
  Button,
  Flex,
  Heading,
  Img,
  Text,
  useDisclosure,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalCloseButton,
  ModalBody,
  Divider,
} from '@chakra-ui/react';
import { useEffect, useState, useContext } from 'react';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

const OrderHistory = ({
  person,
  location,
  startDate,
  startTime,
  price,
  source,
  action,
  serviceStatus,
  serviceProvider,
  bookingplan_amount,
  AmountPaid,
  providerLanguages,
  providerPhoneNumber,
  providerRatings,
  providerExperience,
  providerImage,
  customerName,
}) => {
  useEffect(() => {
    if (
      serviceStatus === 'Open' ||
      serviceStatus === '' ||
      serviceStatus === 'Customer Yet To Revert'
    ) {
      setStatus('In Progress');
      setColor('#EFAD1D');
    } else if (serviceStatus === 'Closed') {
      setStatus('Completed');
      setColor('#1DA912');
    } else {
      setStatus('Cancelled');
      setColor('#D53519');
    }
    const start = new Date(startDate);
    setDate(
      start.toLocaleDateString('en-us', {
        weekday: 'long',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
      })
    );
  }, []);

  const [status, setStatus] = useState('In Progress');
  const [color, setColor] = useState('yellow');
  const [date, setDate] = useState('');
  const { onAvailableOpen } = useContext(ProviderContext);

  const { isOpen, onOpen, onClose } = useDisclosure();
  const [selectedBooking, setSelectedBooking] = useState(null);

  const handleBookingClick = () => {
    setSelectedBooking({
      service_type: person,
      location: location,
      startDate: startDate,
      startTime: startTime,
      serviceStatus: serviceStatus,
      serviceProvider: serviceProvider,
      totalAmount: price,
    });
    onOpen();
  };

  const generatePDF = () => {
    const doc = new jsPDF();

    console.log(
      selectedBooking.user_name,
      selectedBooking.totalAmount,
      selectedBooking.bookingplan_amount
    );

    const invoiceNumber = `INV-${Math.floor(Math.random() * 1000000)
      .toString()
      .padStart(6, '0')}`;

    const invoiceDate = new Date();
    const formattedInvoiceDate = invoiceDate.toLocaleDateString();

    const dueDate = new Date(invoiceDate);
    dueDate.setDate(invoiceDate.getDate() + 15);
    const formattedDueDate = dueDate.toLocaleDateString();

    const addHeader = () => {
      doc.setFontSize(14);
      doc.text(
        'Yellow Sense Technologies Pvt Ltd',
        105,
        15,
        null,
        null,
        'center'
      );

      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(
        'Startup India - Govt of India DP - IIT: DIPP - 138 388 | MSME Udyog Aadhar: UDYAM-KR-03-0293956',
        105,
        25,
        null,
        null,
        'center'
      );
      doc.text(
        'CIN: U-62099-KA-2023-PTC-174648 | PAN: AABCY6908P | TAN: BLRY02955B',
        105,
        35,
        null,
        null,
        'center'
      );
      doc.text(
        '+91 9869397868, +91 7838575893 | hr@yellowsense.in | https://yellowsense.in',
        105,
        45,
        null,
        null,
        'center'
      );

      doc.setLineWidth(0.5);
      doc.line(10, 50, 200, 50);
    };

    const addFooter = (pageNumber) => {
      doc.setLineWidth(0.5);
      doc.line(0, 280, 300, 280);

      doc.setFontSize(10);
      doc.setTextColor(100);
      doc.text(
        'All rights reserved @ Yellow Sense Technologies Pvt Ltd',
        105,
        285,
        null,
        null,
        'center'
      );
      doc.text(
        'Office address: 7th floor, Main Building, Amrita Technology Business Incubator (Amrita TBI), Amrita Vishwa Vidyapeetham',
        105,
        290,
        null,
        null,
        'center'
      );
      doc.text(
        'University Campus, Kasavanahalli, Carmelaram, Bengaluru, Karnataka 560035',
        105,
        295,
        null,
        null,
        'center'
      );
      doc.text(
        'Registered corporate address: F NO 9-C, Lavender Block, Regency Pinnacle Heights, Rachaenahalli, Dr. SRK Nagar, Bengaluru, Karnataka - 560077',
        105,
        300,
        null,
        null,
        'center'
      );
      doc.text('Page ' + pageNumber, 105, 305, null, null, 'center');
    };

    addHeader();

    const logoData =
      'data:image/png;base64,';
    const nameImageData =
      'data:image/png;base64,';

    doc.addImage(logoData, 'PNG', 10, 60, 15, 15);
    doc.addImage(nameImageData, 'PNG', 28, 65, 40, 5);

    const fontSize = 10;
    const lineHeight = 4;
    let startY = 80;

    doc.setFontSize(fontSize);
    doc.setTextColor(0, 0, 0);
    doc.text('YellowSense Technologies', 12, startY);
    doc.setTextColor(100);
    doc.text('Karnataka', 12, (startY += lineHeight));
    doc.text('India', 12, (startY += lineHeight));
    doc.text('9403890108', 12, (startY += lineHeight));
    doc.text('support@yellowsense.in', 12, (startY += lineHeight));

    doc.setTextColor(0, 0, 0);
    doc.setFontSize(20);
    doc.text('TAX INVOICE', 150, 70, null, null, null);
    doc.setTextColor(100);
    doc.setFontSize(10);
    doc.text(`# ${invoiceNumber}`, 195, 75, null, null, 'right');
    doc.setTextColor(0, 0, 0);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'bold');
    doc.text('Balance Due', 195, 85, null, null, 'right');
    doc.text(
      `${selectedBooking.totalAmount - AmountPaid}.00`,
      195,
      89,
      null,
      null,
      'right'
    );

    const invoiceFontSize = 10;
    const invoiceLineHeight = 5;
    let invoiceStartY = 100;

    doc.setTextColor(0, 0, 0);
    doc.setFont('helvetica', '400');
    doc.setFontSize(invoiceFontSize);
    doc.text(
      `Invoice Date: ${formattedInvoiceDate}`,
      195,
      (invoiceStartY += invoiceLineHeight),
      null,
      null,
      'right'
    );
    doc.text(
      'Terms: Due on Receipt',
      195,
      (invoiceStartY += invoiceLineHeight),
      null,
      null,
      'right'
    );
    doc.text(
      `Due Date: ${formattedDueDate}`,
      195,
      (invoiceStartY += invoiceLineHeight),
      null,
      null,
      'right'
    );

    doc.setFontSize(10);
    doc.setFont('helvetica', '500');
    doc.text(`Customer: ${customerName}`, 12, 120);

    doc.autoTable({
      startY: 130,
      head: [['#', 'Description', 'Service Charge', 'Booking Charge', 'Total']],
      body: [
        [
          1,
          selectedBooking.service_type,
          Number(selectedBooking.totalAmount).toFixed(2),
          Number(bookingplan_amount).toFixed(2),
          Number(
            Number(selectedBooking.totalAmount) + Number(bookingplan_amount)
          ).toFixed(2),
        ],
      ],
    });

    const finalY = doc.lastAutoTable.finalY;
    doc.setFont('helvetica', '500');
    doc.setFontSize(10);
    doc.text(
      `Sub Total: ${
        Number(selectedBooking.totalAmount) + Number(bookingplan_amount)
      }.00`,
      190,
      finalY + 10,
      null,
      null,
      'right'
    );
    doc.text(
      `Total: ${
        Number(selectedBooking.totalAmount) + Number(bookingplan_amount)
      }.00`,
      190,
      finalY + 17,
      null,
      null,
      'right'
    );
    doc.text(`Payment Made: `, 180, finalY + 24, null, null, 'right');
    doc.setTextColor(255, 0, 0);
    doc.text(
      ` -${Number(bookingplan_amount)}.00`,
      190,
      finalY + 24,
      null,
      null,
      'right'
    );
    doc.setTextColor(0, 0, 0);
    doc.text(
      `Due Amount: ${
        Number(selectedBooking.totalAmount) +
        Number(bookingplan_amount) -
        Number(bookingplan_amount)
      }.00`,
      190,
      finalY + 31,
      null,
      null,
      'right'
    );

    doc.setTextColor(0, 0, 0);
    doc.setFontSize(10);
    doc.setFont('helvetica', '500');
    doc.text('Thanks for your business.', 10, finalY + 60);
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.2);
    doc.line(10, finalY + 68, 60, finalY + 68);

    addFooter();

    doc.save(`invoice_${invoiceNumber}.pdf`);
  };

  return (
    <Box>
      <Flex
        bg="#FFFFE9"
        borderRadius="80px"
        alignItems="center"
        justifyContent="space-around"
        p="1.5rem"
        my="2%"
        boxShadow="rgba(0, 0, 0, 0.24) 0px 3px 8px"
        flexDirection={{ base: 'column', md: 'row' }}
        gap={{ base: '30px' }}
        onClick={handleBookingClick}
        cursor="pointer"
      >
        {(serviceStatus == 'Open' ||
          serviceStatus == '' ||
          serviceStatus === 'Customer Yet To Revert') &&
        source != 'order' ? (
          <Img
            w={{ md: '5rem', base: '10rem' }}
            src={`images/search.webp`}
            alt="service"
          />
        ) : (
          <Img
            borderRadius="80px 0px 0px 80px"
            w={{ md: '5rem', base: '10rem' }}
            src={`images/${person.toLowerCase()} (2).webp`}
            alt="service"
          />
        )}
        <Box textAlign={{ md: 'left', base: 'center' }}>
          <Heading size={{ md: 'md', base: '2xl' }}>Booking {person}</Heading>
          <Text my="5%" fontSize={{ md: '1rem', base: '1.5rem' }}>
            {location}
          </Text>
          {bookingplan_amount ? (
            <Text color="green" fontWeight="600">
              Amount Paid: ₹{bookingplan_amount}/-
            </Text>
          ) : null}

          <Text>
            {date} , {startTime}
          </Text>
          {source != 'order' && serviceProvider != '' && (
            <Flex
              alignItems="center"
              justifyContent={{ base: 'center', md: 'flex-start' }}
            >
              {serviceProvider ? (
                <>
                  <Text>{person} Name : </Text>
                  <Text color="black" p="2% 4%" borderRadius="20px">
                    {serviceProvider}
                  </Text>
                </>
              ) : (
                <Text>{person} Not Assigned</Text>
              )}
            </Flex>
          )}
        </Box>

        <Flex
          alignItems="center"
          flexDirection={{ md: 'column' }}
          w={{ base: '100%', md: '30%' }}
          justifyContent="space-between"
        >
          <Heading size="md" color="#A15942" mb={{ md: '10%' }}>
            ₹ {price}
          </Heading>
          {source == 'order' ? (
            <Button
              my="5%"
              bg="#A15942"
              borderRadius="30px"
              color="white"
              onClick={action}
              _hover={{}}
            >
              Proceed
            </Button>
          ) : (
            <Button
              _hover={{}}
              my="5%"
              bg={color}
              mx="auto"
              p={{ base: '10%' }}
              fontSize={{ md: '1rem', base: '1.8rem' }}
              borderRadius="30px"
              color="white"
            >
              {status}
            </Button>
          )}
        </Flex>
      </Flex>
      {(serviceStatus == 'Open' ||
        serviceStatus == '' ||
        serviceStatus === 'Customer Yet To Revert') &&
        source != 'order' && (
          <Text textAlign="center" color="#AD6A4D">
            Please wait for a while our team provides you the best {person}
          </Text>
        )}

      <Modal
        isCentered
        size={{ md: 'lg', base: 'xs' }}
        isOpen={isOpen}
        onClose={onClose}
      >
        <ModalOverlay />
        <ModalContent borderRadius="30px" bg="#FFFFE9">
          <ModalHeader bg="#FFED9B" pb="0px" borderRadius="30px">
            <Heading size="lg" color="#a15942" p="1%">
              Booking Details
            </Heading>
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            {selectedBooking && (
              <Box>
                <Text mb="2%" mt="1%">
                  <strong>Service Type:</strong> {selectedBooking.service_type}
                </Text>
                <Text mb="2%">
                  <strong>Location:</strong> {selectedBooking.location}
                </Text>
                <Text mb="2%">
                  <strong>Start Date:</strong> {selectedBooking.startDate}
                </Text>
                <Text mb="2%">
                  <strong>Start Time:</strong> {selectedBooking.startTime}
                </Text>
                <Text mb="2%">
                  <strong>Status:</strong> {selectedBooking.serviceStatus}
                </Text>
                <Text mb="2%">
                  <strong>Service Plan:</strong> ₹{bookingplan_amount}/-
                </Text>
                <Text mb="2%">
                  <strong>Total Amount:</strong> ₹{selectedBooking.totalAmount}
                </Text>
                <Text mb="2%">
                  <strong>Amount Paid: </strong>₹{AmountPaid ? AmountPaid : 0}
                </Text>
                <Text mb="2%">
                  <strong>Due Amount: </strong>₹
                  {selectedBooking.totalAmount - AmountPaid}
                </Text>
                {selectedBooking.serviceProvider ? (
                  <>
                    <Text mb="2%">
                      <strong>{person} Name :</strong>{' '}
                      {selectedBooking.serviceProvider}
                    </Text>
                    <Text mb="2%">
                      <strong>{person} Phone :</strong> {providerPhoneNumber}
                    </Text>
                    <Text mb="2%">
                      <strong>{person} Languages Speaks :</strong>{' '}
                      {providerLanguages}
                    </Text>
                    <Text mb="2%">
                      <strong>{person} Ratings:</strong>
                      {providerRatings}
                    </Text>
                    <Text mb="2%">
                      <strong>{person} Experience : </strong>
                      {providerExperience ? providerExperience : 0} years
                    </Text>
                  </>
                ) : (
                  <Text>{person} Not Assigned</Text>
                )}
              </Box>
            )}
          </ModalBody>
          <Button mt="4" colorScheme="teal" onClick={generatePDF}>
            Download Invoice
          </Button>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default OrderHistory;
